#!/bin/bash
# Fix Gradle files generated by flutter create.
# Flutter 3.47.5 generates build.gradle.kts (Kotlin DSL) with readWithUTF8()
# which was removed in Gradle 9.x. Replace with proper Groovy .gradle files.
cd android

# Remove Kotlin DSL files (Flutter generates them but they use incompatible syntax)
rm -f build.gradle.kts settings.gradle.kts app/build.gradle.kts

# Replace project-level build.gradle with working Groovy
cat > build.gradle << 'EOF'
buildscript {
    repositories {
        google()
        mavenCentral()
    }
    dependencies {
        classpath 'com.android.tools.build:gradle:8.2.0'
        classpath 'org.jetbrains.kotlin:kotlin-gradle-plugin:2.0.0'
    }
}

allprojects {
    repositories {
        google()
        mavenCentral()
    }
}
EOF

# Replace settings.gradle.kts with Groovy including pluginManagement for Flutter plugin
cat > settings.gradle << 'EOF'
pluginManagement {
    repositories {
        gradlePluginPortal()
        google()
        mavenCentral()
    }
}

include ':app'
EOF

# Replace app-level build.gradle with working Groovy using Flutter Gradle Plugin declarative block
cat > app/build.gradle << 'GRADLE_EOF'
plugins {
    id 'com.android.application'
    id 'org.jetbrains.kotlin.android'
    id 'dev.flutter.flutter-gradle-plugin' version '3.47.5'
}

def localProperties = new Properties()
def localPropertiesFile = rootProject.file('local.properties')
if (localPropertiesFile.exists()) {
    localPropertiesFile.withReader('UTF-8') { reader ->
        localProperties.load(reader)
    }
}
def flutterRoot = localProperties.getProperty('flutter.sdk')
if (flutterRoot == null) {
    throw new GradleException("Flutter SDK not found. Define location with flutter.sdk in the local.properties file.")
}
def flutterVersionCode = localProperties.getProperty('flutterVersionCode') ?: '1'
def flutterVersionName = localProperties.getProperty('flutterVersionName') ?: '1.0.0'

android {
    namespace = "com.helix.helix"
    compileSdkVersion 34
    compileOptions {
        sourceCompatibility JavaVersion.VERSION_1_8
        targetCompatibility JavaVersion.VERSION_1_8
    }
    sourceSets { main.java.srcDirs += 'src/main/kotlin' }
    defaultConfig {
        applicationId "com.helix.helix"
        minSdkVersion 21
        targetSdkVersion 34
        versionCode flutterVersionCode.toInteger()
        versionName flutterVersionName
    }
    buildTypes { release { signingConfig signingConfigs.debug } }
}

dependencies {
    implementation "org.jetbrains.kotlin:kotlin-stdlib-jdk8:2.0.0"
    implementation "androidx.core:core-ktx:+"
    implementation "androidx.annotation:annotation:+"
    implementation "androidx.lifecycle:lifecycle-runtime-ktx:+"
    implementation "androidx.activity:activity:+"
}

flutter {
    source '../..'
}
GRADLE_EOF

echo "Gradle files fixed"
